// ─────────────────────────────────────────────────────────────────────
// Envía 4 renders a Shotstack (escenario stage = gratuito para test).
// Cada render mezcla vídeo Higgsfield + voz ElevenLabs + subtítulos
// en tipografía Senda Natural: DM Sans 500, crema #FAF6F0, fondo oscuro.
//
// Cambiar a https://api.shotstack.io/v1/render en producción.
// ─────────────────────────────────────────────────────────────────────

const input = $input.first().json;
const data = input.body || input;

const SHOTSTACK_KEY = $vars.SHOTSTACK_API_KEY;
const SHOTSTACK_URL = 'https://api.shotstack.io/stage/render';

const pairs = [
  { key: 'ig1',     video: data.ig1_video,     audio: data.ig1_audio },
  { key: 'ig2',     video: data.ig2_video,     audio: data.ig2_audio },
  { key: 'tiktok1', video: data.tiktok1_video, audio: data.tiktok1_audio },
  { key: 'tiktok2', video: data.tiktok2_video, audio: data.tiktok2_audio },
];

const buildPayload = (videoUrl, audioUrl) => ({
  timeline: {
    background: '#000000',
    tracks: [
      {
        clips: [{
          asset: {
            type: 'video',
            src: videoUrl,
            volume: 0
          },
          start: 0,
          length: 'auto',
          fit: 'crop'
        }]
      },
      {
        clips: [{
          asset: {
            type: 'audio',
            src: audioUrl,
            volume: 1
          },
          start: 0,
          length: 'auto'
        }]
      },
      {
        clips: [{
          asset: {
            type: 'caption',
            src: audioUrl,
            font: {
              family: 'DM Sans',
              size: 50,
              color: '#FAF6F0ff',
              weight: '500'
            },
            background: {
              color: '#0E0D0Ab3',
              borderRadius: 12,
              padding: '12 18'
            },
            align: 'center',
            position: 'bottomCenter',
            offset: { y: 0.1 },
            lineLength: 4,
            lines: 1,
            transition: { in: 'fade', out: 'fade' }
          },
          start: 0,
          length: 'auto'
        }]
      }
    ]
  },
  output: {
    format: 'mp4',
    resolution: 'hd',
    aspectRatio: '9:16',
    fps: 25
  }
});

const renderIds = {};

for (const { key, video, audio } of pairs) {
  if (!video || !audio) {
    renderIds[key] = null;
    continue;
  }

  const res = await $helpers.httpRequest({
    method: 'POST',
    url: SHOTSTACK_URL,
    headers: {
      'x-api-key': SHOTSTACK_KEY,
      'Content-Type': 'application/json'
    },
    body: buildPayload(video, audio)
  });

  renderIds[key] = res.response?.id || null;
  await new Promise(r => setTimeout(r, 600));
}

return [{
  json: {
    dia: data.dia,
    tema: data.tema,
    ig1_video:     data.ig1_video,
    ig2_video:     data.ig2_video,
    tiktok1_video: data.tiktok1_video,
    tiktok2_video: data.tiktok2_video,
    ig1:     renderIds.ig1,
    ig2:     renderIds.ig2,
    tiktok1: renderIds.tiktok1,
    tiktok2: renderIds.tiktok2
  }
}];

// Verifica el estado de los 4 renders de Shotstack.
// Retorna URLs si están listos, pendingCount=0 si todos completados.

const data = $input.first().json;
const SHOTSTACK_KEY = $vars.SHOTSTACK_API_KEY;
const BASE_URL = 'https://api.shotstack.io/stage/render';
const KEYS = ['ig1', 'ig2', 'tiktok1', 'tiktok2'];

const result = { ...data };
let pendingCount = 0;

for (const key of KEYS) {
  const renderId = data[key];
  if (!renderId) {
    pendingCount++;
    continue;
  }

  const res = await $helpers.httpRequest({
    method: 'GET',
    url: `${BASE_URL}/${renderId}`,
    headers: { 'x-api-key': SHOTSTACK_KEY }
  });

  const { status, url } = res.response || {};

  if (status === 'done' && url) {
    result[`${key}_url`] = url;
  } else if (status === 'failed') {
    result[`${key}_error`] = `Render fallido: ${renderId}`;
    pendingCount++;
  } else {
    pendingCount++;
  }

  await new Promise(r => setTimeout(r, 250));
}

result.pendingCount = pendingCount;
return [{ json: result }];

// Segunda verificación de renders.
const data = $input.first().json;
const SHOTSTACK_KEY = $vars.SHOTSTACK_API_KEY;
const BASE_URL = 'https://api.shotstack.io/stage/render';
const KEYS = ['ig1', 'ig2', 'tiktok1', 'tiktok2'];

const result = { ...data };
let pendingCount = 0;

for (const key of KEYS) {
  if (result[`${key}_url`]) continue;

  const renderId = data[key];
  if (!renderId) { pendingCount++; continue; }

  const res = await $helpers.httpRequest({
    method: 'GET',
    url: `${BASE_URL}/${renderId}`,
    headers: { 'x-api-key': SHOTSTACK_KEY }
  });

  const { status, url } = res.response || {};

  if (status === 'done' && url) {
    result[`${key}_url`] = url;
  } else {
    pendingCount++;
  }

  await new Promise(r => setTimeout(r, 250));
}

result.pendingCount = pendingCount;
return [{ json: result }];

